import http.server,os
os.chdir("build/web")
class H(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        if not os.path.exists(self.path.split("?")[0].lstrip("/")) : self.path="/index.html"
        return super().do_GET()
http.server.ThreadingHTTPServer(("127.0.0.1",5601),H).serve_forever()
